// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint8 steps) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        uint256 n = bound(uint256(steps), 1, 5);
        address caller = makeAddr("caller");
        vm.deal(caller, amount * n);
        for (uint256 i = 0; i < n; i++) {
            vm.prank(caller);
            c.Put{value: amount}(0);
        }
        uint256 totalBalance;
        uint256 counter = 0;
        while (true) {
            uint256 keysLen = 100;
            address[] memory addrs = new address[](keysLen);
            uint256[] memory vals = new uint256[](keysLen);
            uint256 fetched = this.getAccEntries(c, counter, keysLen, addrs, vals);
            for (uint256 j = 0; j < fetched; j++) {
                totalBalance += vals[j];
            }
            if (fetched < keysLen) break;
            counter += fetched;
        }
        assertTrue(totalBalance <= address(c).balance || totalBalance == address(c).balance);
    }

    function getAccEntries(C target, uint256 start, uint256 count, address[] memory addrs, uint256[] memory vals) external view returns (uint256) {
        // This helper reads public mapping entries via the auto-generated getter.
        // Since mapping getters require the key, we need known keys. We populate keys from events or history.
        // In this test we rely on the caller being the only depositor.
        // We return the number of entries processed.
        // We only access the getter for the address we know: the caller.
        // To make this generic for fuzz, we assume only one caller.
        // For a single caller, the mapping access is straightforward.
        (uint256 unlockTime, uint256 balance) = target.Acc(addrs[0]);
        vals[0] = balance;
        return 1;
    }
}

contract AccHelper {
    function getAcc(C target, address holder) external view returns (uint256, uint256) {
        return target.Acc(holder);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 _value) public {
        // Restrict to a wide domain where overflow can happen (balance + value overflows uint256)
        vm.deal(address(this), _value);
        // Ensure we start with a balance high enough that adding _value overflows
        // We can set up a pre-existing balance by making a Put in setUp, but simpler:
        // We just need a sender whose balance is near max. Use a fresh address for each fuzz run.
        address sender = address(uint160(uint256(keccak256(abi.encodePacked(_value)))));
        // Make sure sender is not address(this) and has no balance yet
        vm.assume(sender != address(this));
        // Pre-set the sender's balance in c to near max.
        // We can do a direct Put, but that would succeed. Instead, we need to set acc.balance externally?
        // We cannot use vm.store. So we need to use c's Put to build up balance.
        // But that would require many operations. To simplify, we assume the fuzzer can pick any balance
        // that already exists. So we just call Put with a value that triggers overflow from zero?
        // The overflow check is: require((acc.balance + msg.value) >= acc.balance);
        // If acc.balance is zero, any value works, but overflow can still happen if balance + value overflows.
        // Actually, overflow from zero? Zero + value = value, no overflow unless value = type(uint256).max?
        // Not practical. We need a pre-existing balance such that balance + value overflows.
        // We can achieve that by making two consecutive Puts from the same sender.
        // So we can use the same test contract as sender by pranking.
        // But the fuzzer gives us _value and _unlockTime. We need to set balance = type(uint256).max - _value + 1
        // using vm.store is forbidden. So we must use a helper that already has such a balance.
        // However, the rule is about overflow occurring. The reference reverts if overflow would happen.
        // We can construct the scenario by depositing a huge amount via Put, then trying to overflow.
        // But Put itself is the only way to add to balance. So we need to call Put with a value that makes the sum overflow.
        // We can use the sender's own balance by calling Put twice:
        // 1. First Put with huge amount (almost max)
        // 2. Second Put with remaining amount
        // We'll need the test contract to have enough Ether.
        // However, the fuzzer only provides one _value. So we need to use that as the second value and set the first value accordingly.
        // That would hard-code the first value. Better: make the first Put with type(uint256).max - _value + 1?
        // That depends on _value, so we can compute it. We need to fund the test contract with enough Ether.
        // We can use vm.deal to give the test contract huge Ether.
        // Then prank as sender, call c.Put with huge value (max - _value + 1).
        // Then call again with _value.
        // But the first Put may succeed (reference) because no overflow yet. The second Put would trigger overflow if balance is large enough.
        // The reference would revert on second Put, buggy would succeed.
        // That's a valid test. We need to ensure sender has the balance set correctly.
        // We'll need to compute the overflow threshold dynamically.
        // We can use vm.assume(_value > 0) to avoid zero-value call.
        vm.assume(_value > 0);
        uint256 initialBalance = type(uint256).max - _value + 1;
        // We need to get that much Ether into sender's balance in c. We'll use Put with that amount.
        // Fund the test contract (which will be the sender via prank) with enough Ether.
        vm.deal(sender, initialBalance + _value); // Enough for both puts
        vm.startPrank(sender);
        // First Put with initialBalance
        c.Put{value: initialBalance}(_unlockTime);
        // Now sender's balance in c is initialBalance
        // Second Put with _value, this should overflow because initialBalance + _value = max + 1 = 0 (overflow)
        // Reference should revert, buggy should not revert or revert differently?
        // The buggy version removes the require, so it will add and overflow, no revert.
        // We need to capture whether the second Put reverted.
        bool succeeded = true;
        try c.Put{value: _value}(_unlockTime) { succeeded = true; } catch { succeeded = false; }
        vm.stopPrank();
        // Now, the reference (P) should have reverted (succeeded = false) because overflow check fails.
        // The buggy version (M) should have succeeded (succeeded = true).
        // The invariant: For all admissible inputs, the Put call that would cause a balance overflow MUST revert.
        // The buggy version allows it to not revert.
        // But the reference satisfies: if overflow would occur, it reverts. So we assert that the second Put reverted in reference.
        // However, the test is run against both versions. The reference always reverts, buggy always succeeds.
        // So the assertion should be: succeeded == false.
        // But the problem says the reference ALWAYS satisfies the rule for EVERY input. So we assert that the reference obeys the property.
        // In the reference, succeeded is false. In buggy, succeeded is true. The fuzzer will try many values and find the case where reference passes (succeeded false) and buggy fails (succeeded true).
        // The universal property is: "Put always reverts when msg.value causes an overflow."
        // In our test, we always trigger overflow for the second Put. That's valid because we first set balance to just below overflow.
        // So the assertion: assertTrue(!succeeded);
        // This holds for the reference because it has the require, but the buggy version will have succeeded = true, failing the assertion.
        // That's exactly what we need.
        assertTrue(!succeeded);
    }
}

