pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 msgValue, uint256 unlockTime) public {
        // Restrict msgValue to a wide range that can still trigger overflow
        vm.assume(msgValue > 0);
        address caller = address(0x1234);
        vm.deal(caller, msgValue);

        // Record pre-call state
        uint256 preBalance = c.Acc(caller).balance;
        uint256 preContractBalance = address(c).balance;
        uint256 preSum = preBalance + preContractBalance;

        // Perform the Put call
        vm.prank(caller);
        c.Put{value: msgValue}(unlockTime);

        // Record post-call state
        uint256 postBalance = c.Acc(caller).balance;
        uint256 postContractBalance = address(c).balance;
        uint256 postSum = postBalance + postContractBalance;

        // The sum of caller's balance and contract's balance must not decrease.
        // Reference always satisfies this; buggy can overflow balance, reducing it while ETH still arrives,
        // leading to postSum < preSum.
        assertTrue(postSum >= preSum);
    }
}

