pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 value, uint256 unlockTimeArg, uint256 collectAmt, uint256 warpSecsAfterPut) public {
        // Restrict values to reasonable ranges to avoid overflow or zero collect amounts
        value = bound(value, 1, type(uint128).max);
        collectAmt = bound(collectAmt, 1, type(uint128).max);
        // warpSecsAfterPut is how many seconds after Put we attempt to Collect
        warpSecsAfterPut = bound(warpSecsAfterPut, 0, 365 days);

        address actor = address(0x1000);
        vm.deal(actor, value);

        // Warp to a known timestamp
        vm.warp(1000);

        // Actor performs Put with unlockTimeArg
        vm.prank(actor);
        c.Put{value: value}(unlockTimeArg);

        uint expectedUnlock = unlockTimeArg > 1000 ? unlockTimeArg : 1000;

        // Warp forward to a time that should still be locked according to the reference,
        // but may be unlocked by the buggy version if unlockTimeArg was small.
        vm.warp(1000 + warpSecsAfterPut);

        // Record Collect success
        bool ok = false;
        vm.prank(actor);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference rule: Collect must fail if we warped to a time strictly before the expected unlock time.
        // The buggy version may allow Collect when it should not.
        if (warpSecsAfterPut < expectedUnlock - 1000) {
            assertTrue(!ok);
        } else {
            // If we warped past expected unlock, Collect may succeed depending on balance; no assertion needed
            assertTrue(true);
        }
    }
}

