pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 t1, uint256 t2, uint256 delta) public {
        // t1 and t2 are unlockTime arguments for two successive Put calls
        // delta is the amount by which t2 exceeds t1 >= 1 to guarantee t2 > t1
        vm.assume(delta >= 1 && delta <= type(uint256).max - t1);
        t2 = t1 + delta;
        // Ensure t2 > block.timestamp to make the bug observable
        uint256 currentTime = block.timestamp;
        vm.assume(t2 > currentTime);

        // Use two different arbitrary callers
        address alice = address(0x1000);
        address bob = address(0x2000);

        // First Put: alice deposits with unlockTime = t1
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Put{value: 1 ether}(t1);

        // Warp to a future time t1 < now < t2
        uint256 warpTime = t1 + (t2 - t1) / 2;
        // Ensure warpTime is strictly between t1 and t2
        if (warpTime <= currentTime || warpTime <= t1 || warpTime >= t2) {
            warpTime = t1 + 1;
            if (warpTime >= t2) {
                warpTime = t1 + (t2 - t1) / 2;
            }
        }
        vm.warp(warpTime);

        // Second Put: bob deposits with a strictly greater unlockTime = t2
        vm.deal(bob, 2 ether);
        vm.prank(bob);
        c.Put{value: 2 ether}(t2);

        // After the second Put, bob's unlockTime must equal t2 (reference gives max(t2, warpTime) = t2)
        // Bug sets it to block.timestamp (warpTime), which is < t2
        (uint storedUnlockTime, uint storedBalance) = c.Acc(bob);
        assertTrue(storedUnlockTime == t2);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint unlockTime, uint deposit, uint collectAmt) public payable {
        require(deposit > 0 && collectAmt > 0 && deposit >= collectAmt);
        require(address(this).balance >= deposit);
        c.Put{value: deposit}(unlockTime);
        uint balBefore = c.Acc(address(this)).balance;
        bool ok = false;
        assembly { ok := lt(timestamp(), unlockTime) }
        if (ok) { return; }
        c.Collect(collectAmt);
        uint balAfter = c.Acc(address(this)).balance;
        assert(balAfter == balBefore - collectAmt);
    }
}

